local PL=Players

----------------------------------------------------------------
-- CLEAN UNLOAD INFRASTRUCTURE
-- * running the script twice first unloads the previous copy
-- * every connection goes through Bind() so closing the menu disconnects ALL of them
-- * every background loop checks Alive and stops when the menu is closed
----------------------------------------------------------------
local ENV=(getgenv and getgenv()) or _G
if ENV.K24HUB_Unload then pcall(ENV.K24HUB_Unload) end

local Alive=true
local Conns={}
local function Bind(sig,fn)
    local c=sig:Connect(fn)
    Conns[#Conns+1]=c
    return c
end

----------------------------------------------------------------
-- KEYBIND HELPERS
-- Allowed modifiers: Ctrl, Shift, Alt. Blocked keys: W A S D Q E F and Windows.
----------------------------------------------------------------
local KB={listening=false,stamp=0}
local MOD_KEYS={
    Ctrl={Enum.KeyCode.LeftControl,Enum.KeyCode.RightControl},
    Shift={Enum.KeyCode.LeftShift,Enum.KeyCode.RightShift},
    Alt={Enum.KeyCode.LeftAlt,Enum.KeyCode.RightAlt},
}
local MOD_ORDER={"Ctrl","Shift","Alt"}
local BLOCKED={
    [Enum.KeyCode.W]=true,[Enum.KeyCode.A]=true,[Enum.KeyCode.S]=true,[Enum.KeyCode.D]=true,
    [Enum.KeyCode.Q]=true,[Enum.KeyCode.E]=true,[Enum.KeyCode.F]=true,
    [Enum.KeyCode.LeftSuper]=true,[Enum.KeyCode.RightSuper]=true,
    [Enum.KeyCode.LeftMeta]=true,[Enum.KeyCode.RightMeta]=true,
}
local function ModOfKey(kc)
    for _,m in ipairs(MOD_ORDER) do
        if table.find(MOD_KEYS[m],kc) then return m end
    end
end
local function HeldMods()
    local s={}
    for _,m in ipairs(MOD_ORDER) do
        for _,k in ipairs(MOD_KEYS[m]) do
            if UIS:IsKeyDown(k) then s[m]=true end
        end
    end
    return s
end
-- exact match: the modifiers held must be exactly the ones saved in the shortcut
local function BindMatches(bind,kc)
    if not bind or kc~=bind.key then return false end
    local own=ModOfKey(kc)
    for _,m in ipairs(MOD_ORDER) do
        if m~=own then
            local held=false
            for _,k in ipairs(MOD_KEYS[m]) do
                if UIS:IsKeyDown(k) then held=true end
            end
            if held~=(bind.mods[m]==true) then return false end
        end
    end
    return true
end
local function BindText(b)
    local p={}
    for _,m in ipairs(MOD_ORDER) do
        if b.mods[m] then p[#p+1]=m end
    end
    p[#p+1]=b.key.Name
    return table.concat(p," + ")
end

----------------------------------------------------------------
-- STUD TEXTURE
-- Your StudTexture.png (one stud, tiled over every panel). If STUD_B64 is nil the script falls back
-- to a texture generated by code.
----------------------------------------------------------------
local STUD_B64=[[]]
local STUD_FILE="K24HUB_stud_v3.png"

local StudAsset
do
    local B64="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup={}
    for i=1,#B64 do lookup[string.byte(B64,i)]=i-1 end

    local function decode(data)
        local out,n,acc,bits={},0,0,0
        for i=1,#data do
            local v=lookup[string.byte(data,i)]
            if v then
                acc=acc*64+v;bits=bits+6
                if bits>=8 then
                    bits=bits-8
                    local p=2^bits
                    local byte=math.floor(acc/p)
                    acc=acc-byte*p
                    n=n+1;out[n]=string.char(byte)
                end
            end
        end
        return table.concat(out)
    end

    -- minimal PNG encoder (RGBA, uncompressed deflate)
    local CRC_T={}
    for n=0,255 do
        local c=n
        for _=1,8 do
            if bit32.band(c,1)==1 then c=bit32.bxor(0xEDB88320,bit32.rshift(c,1)) else c=bit32.rshift(c,1) end
        end
        CRC_T[n]=c
    end
    local function crc32(s)
        local c=0xFFFFFFFF
        for i=1,#s do
            c=bit32.bxor(CRC_T[bit32.band(bit32.bxor(c,s:byte(i)),0xFF)],bit32.rshift(c,8))
        end
        return bit32.bxor(c,0xFFFFFFFF)
    end
    local function be32(n)
        return string.char(bit32.band(bit32.rshift(n,24),255),bit32.band(bit32.rshift(n,16),255),bit32.band(bit32.rshift(n,8),255),bit32.band(n,255))
    end
    local function chunk(tag,data)
        local body=tag..data
        return be32(#data)..body..be32(crc32(body))
    end
    local function adler32(s)
        local a,b=1,0
        for i=1,#s do
            a=(a+s:byte(i))%65521
            b=(b+a)%65521
        end
        return b*65536+a
    end
    local function zlibStored(raw)
        local out={"\120\1"}
        local pos,n=1,#raw
        while pos<=n do
            local len=math.min(65535,n-pos+1)
            local final=(pos+len>n) and 1 or 0
            local nlen=65535-len
            out[#out+1]=string.char(final,len%256,math.floor(len/256),nlen%256,math.floor(nlen/256))
            out[#out+1]=raw:sub(pos,pos+len-1)
            pos=pos+len
        end
        out[#out+1]=be32(adler32(raw))
        return table.concat(out)
    end
    local function makeStudPNG(size)
        local rows={}
        local c=(size-1)/2
        local R=size*0.30
        for y=0,size-1 do
            local row={"\0"}
            for x=0,size-1 do
                local dx,dy=x-c,y-c
                local d=math.sqrt(dx*dx+dy*dy)
                local r,g,b,a=255,255,255,0
                if d<=R then
                    -- stud top: bright, with a highlight toward the top-left
                    local hx,hy=dx+R*0.35,dy+R*0.35
                    local hl=math.clamp(1-math.sqrt(hx*hx+hy*hy)/(R*1.2),0,1)
                    a=math.floor(120+110*hl)
                elseif d<=R+1.8 then
                    -- dark rim (darker toward the bottom-right)
                    local shade=math.clamp((dx+dy)/(R*2)+0.5,0,1)
                    r,g,b=0,math.floor(30+20*(1-shade)),math.floor(90+40*(1-shade))
                    a=math.floor(90+70*shade)
                elseif d<=R+4 then
                    -- soft shadow under the stud
                    r,g,b=0,20,80
                    a=math.floor(40*(1-(d-R-1.8)/2.2))
                end
                row[#row+1]=string.char(r,g,b,math.clamp(a,0,255))
            end
            rows[#rows+1]=table.concat(row)
        end
        local raw=table.concat(rows)
        return "\137PNG\r\n\26\n"
            ..chunk("IHDR",be32(size)..be32(size).."\8\6\0\0\0")
            ..chunk("IDAT",zlibStored(raw))
            ..chunk("IEND","")
    end

    pcall(function()
        local getAsset=getcustomasset or getsynasset
        if not (writefile and getAsset) then return end
        if not (isfile and isfile(STUD_FILE)) then
            local bytes
            if type(STUD_B64)=="string" and #STUD_B64>20 then bytes=decode(STUD_B64) else bytes=makeStudPNG(64) end
            writefile(STUD_FILE,bytes)
        end
        StudAsset=getAsset(STUD_FILE)
    end)
end

----------------------------------------------------------------
-- UI HELPERS
----------------------------------------------------------------
local Theme={
    blue=Color3.fromRGB(34,130,255),
    blueLight=Color3.fromRGB(90,190,255),
    navy=Color3.fromRGB(6,22,70),
    navy2=Color3.fromRGB(10,36,105),
    cyan=Color3.fromRGB(90,215,255),
    white=Color3.new(1,1,1),
    off=Color3.fromRGB(48,62,110),
    on=Color3.fromRGB(60,220,120),
    red=Color3.fromRGB(235,60,60),
    gold=Color3.fromRGB(255,190,40),
}

local function make(class,props,parent)
    local o=Instance.new(class)
    for k,v in pairs(props or {}) do o[k]=v end
    if parent then o.Parent=parent end
    return o
end
local function round(o,r) make("UICorner",{CornerRadius=UDim.new(0,r or 8)},o);return o end
local function stroke(o,color,th,tr)
    return make("UIStroke",{Color=color,Thickness=th or 1,Transparency=tr or 0,ApplyStrokeMode=Enum.ApplyStrokeMode.Border},o)
end
local function styleText(o)
    o.TextStrokeColor3=Color3.fromRGB(0,20,70)
    o.TextStrokeTransparency=0.55
end
local function tween(o,t,props,style,dir)
    TS:Create(o,TweenInfo.new(t,style or Enum.EasingStyle.Quad,dir or Enum.EasingDirection.Out),props):Play()
end
local function safe(cb,...)
    if type(cb)~="function" then return end
    local args=table.pack(...)
    task.spawn(function()
        local ok,err=pcall(cb,table.unpack(args,1,args.n))
        if not ok then warn("[K24 HUB] "..tostring(err)) end
    end)
end
-- tiled stud overlay (repeats the texture to fill the whole panel)
local function studs(parent,tint,transp,tile,radius)
    if not StudAsset then return end
    local img=make("ImageLabel",{
        Name="Studs",BackgroundTransparency=1,Size=UDim2.fromScale(1,1),Image=StudAsset,
        ScaleType=Enum.ScaleType.Tile,TileSize=UDim2.fromOffset(tile or 64,tile or 64),
        ImageColor3=tint or Theme.white,ImageTransparency=0.45,BorderSizePixel=0,
    },parent)
    if radius then round(img,radius) end
end
local function guiParent(gui)
    local ok=pcall(function()
        if syn and syn.protect_gui then syn.protect_gui(gui) end
        gui.Parent=(gethui and gethui()) or game:GetService("CoreGui")
    end)
    if not ok or not gui.Parent then gui.Parent=LP:WaitForChild("PlayerGui") end
end

----------------------------------------------------------------
-- INTRO: "K24 HUB" smooth scale animation, closes, then the menu opens
----------------------------------------------------------------
do
    local intro=make("ScreenGui",{Name="K24Intro",ResetOnSpawn=false,IgnoreGuiInset=true,DisplayOrder=10000})
    guiParent(intro)

    local box=make("Frame",{
        AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.fromScale(0.5,0.5),Size=UDim2.fromOffset(340,120),
        BackgroundColor3=Theme.white,BorderSizePixel=0,
    },intro)
    round(box,16)
    make("UIGradient",{Color=ColorSequence.new(Color3.fromRGB(46,148,255),Color3.fromRGB(12,58,175)),Rotation=90},box)
    local bs=stroke(box,Theme.navy,3)
    studs(box,Theme.white,0,24,16)
    local scale=make("UIScale",{Scale=0},box)

    local lbl=make("TextLabel",{
        BackgroundTransparency=1,Size=UDim2.fromScale(1,1),Font=Enum.Font.FredokaOne,Text="K24 HUB",
        TextSize=54,TextColor3=Theme.white,
    },box)
    styleText(lbl)
    local bar=make("Frame",{
        AnchorPoint=Vector2.new(0.5,0),Position=UDim2.new(0.5,0,1,-16),Size=UDim2.fromOffset(0,4),
        BackgroundColor3=Theme.cyan,BorderSizePixel=0,
    },box)
    round(bar,2)

    tween(scale,0.7,{Scale=1},Enum.EasingStyle.Back)
    task.wait(0.35)
    tween(bar,0.9,{Size=UDim2.fromOffset(190,4)},Enum.EasingStyle.Quint)
    task.wait(1.4)

    tween(scale,0.5,{Scale=0},Enum.EasingStyle.Quint,Enum.EasingDirection.In)
    tween(lbl,0.4,{TextTransparency=1,TextStrokeTransparency=1})
    tween(bs,0.4,{Transparency=1})
    task.wait(0.55)
    intro:Destroy()
end

----------------------------------------------------------------
-- STUD UI LIBRARY (small Rayfield-like API: window, tabs, sections, labels,
-- buttons, toggles, sliders, dropdowns, color pickers, keybinds)
-- UI:Notify is routed to the animated top-right toast system.
----------------------------------------------------------------
local UI={}
local UIgui

function UI:Notify(o)
    if UI.OnNotify then pcall(UI.OnNotify,o) end
end

function UI:CreateWindow(opts)
    local gui=make("ScreenGui",{
        Name=game:GetService("HttpService"):GenerateGUID(false),ResetOnSpawn=false,IgnoreGuiInset=true,
        ZIndexBehavior=Enum.ZIndexBehavior.Sibling,DisplayOrder=9999,
    })
    guiParent(gui)
    UIgui=gui

    local vp=(WS.CurrentCamera or CAM).ViewportSize
    local W=math.min(600,vp.X-20)
    local H=math.min(420,vp.Y-20)

    local Main=make("Frame",{
        Name="Main",AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.fromScale(0.5,0.5),Size=UDim2.fromOffset(W,H),
        BackgroundColor3=Theme.white,BorderSizePixel=0,
    },gui)
    round(Main,14);stroke(Main,Theme.navy,3)
    make("UIGradient",{Color=ColorSequence.new(Color3.fromRGB(46,148,255),Color3.fromRGB(12,58,175)),Rotation=90},Main)
    studs(Main,Theme.white,0,24,14)
    local scale=make("UIScale",{Scale=0},Main)

    -- Header
    local Header=make("Frame",{
        Position=UDim2.fromOffset(6,6),Size=UDim2.new(1,-12,0,44),BackgroundColor3=Theme.white,BorderSizePixel=0,
    },Main)
    round(Header,10);stroke(Header,Theme.navy,2)
    make("UIGradient",{Color=ColorSequence.new(Color3.fromRGB(110,200,255),Color3.fromRGB(30,110,235)),Rotation=90},Header)
    studs(Header,Theme.white,0,24,10)
    local icon=make("Frame",{Position=UDim2.fromOffset(8,7),Size=UDim2.fromOffset(30,30),BackgroundColor3=Theme.white,BorderSizePixel=0},Header)
    round(icon,8);stroke(icon,Theme.navy,2)
    make("TextLabel",{
        BackgroundTransparency=1,Size=UDim2.fromScale(1,1),Font=Enum.Font.FredokaOne,Text="K",TextSize=20,
        TextColor3=Color3.fromRGB(30,110,235),
    },icon)
    local title=make("TextLabel",{
        BackgroundTransparency=1,Position=UDim2.fromOffset(46,0),Size=UDim2.new(1,-130,1,0),Font=Enum.Font.FredokaOne,
        Text=tostring(opts.Name or "HUB"),TextSize=22,TextColor3=Theme.white,TextXAlignment=Enum.TextXAlignment.Left,
    },Header)
    styleText(title)
    local closeBtn=make("TextButton",{
        Position=UDim2.new(1,-38,0.5,-15),Size=UDim2.fromOffset(30,30),BackgroundColor3=Theme.red,AutoButtonColor=true,
        Font=Enum.Font.FredokaOne,Text="X",TextSize=17,TextColor3=Theme.white,BorderSizePixel=0,
    },Header)
    round(closeBtn,8);stroke(closeBtn,Theme.navy,2);styleText(closeBtn)
    local minBtn=make("TextButton",{
        Position=UDim2.new(1,-74,0.5,-15),Size=UDim2.fromOffset(30,30),BackgroundColor3=Theme.gold,AutoButtonColor=true,
        Font=Enum.Font.FredokaOne,Text="–",TextSize=20,TextColor3=Theme.white,BorderSizePixel=0,
    },Header)
    round(minBtn,8);stroke(minBtn,Theme.navy,2);styleText(minBtn)

    -- Drag (header)
    do
        local dragging,ds,sp=false,nil,nil
        Header.InputBegan:Connect(function(i)
            if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then
                dragging=true;ds=i.Position;sp=Main.Position
            end
        end)
        Bind(UIS.InputChanged,function(i)
            if dragging and (i.UserInputType==Enum.UserInputType.MouseMovement or i.UserInputType==Enum.UserInputType.Touch) then
                local d=i.Position-ds
                Main.Position=UDim2.new(sp.X.Scale,sp.X.Offset+d.X,sp.Y.Scale,sp.Y.Offset+d.Y)
            end
        end)
        Bind(UIS.InputEnded,function(i)
            if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then dragging=false end
        end)
    end

    -- Body: sidebar + content
    local Body=make("Frame",{BackgroundTransparency=1,Position=UDim2.fromOffset(10,58),Size=UDim2.new(1,-20,1,-68)},Main)
    local Side=make("Frame",{Size=UDim2.new(0,124,1,0),BackgroundColor3=Theme.navy,BackgroundTransparency=0.2,BorderSizePixel=0},Body)
    round(Side,10);stroke(Side,Theme.cyan,1.5,0.5)
    studs(Side,Theme.white,0,24,10)
    local TabList=make("ScrollingFrame",{
        BackgroundTransparency=1,BorderSizePixel=0,Size=UDim2.fromScale(1,1),ScrollBarThickness=0,
        CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,
    },Side)
    make("UIListLayout",{Padding=UDim.new(0,6),SortOrder=Enum.SortOrder.LayoutOrder},TabList)
    make("UIPadding",{PaddingTop=UDim.new(0,8),PaddingLeft=UDim.new(0,8),PaddingRight=UDim.new(0,8),PaddingBottom=UDim.new(0,8)},TabList)

    local Content=make("Frame",{
        Position=UDim2.new(0,134,0,0),Size=UDim2.new(1,-134,1,0),BackgroundColor3=Theme.navy,BackgroundTransparency=0.35,BorderSizePixel=0,
    },Body)
    round(Content,10);stroke(Content,Theme.cyan,1.5,0.5)
    studs(Content,Theme.white,0,24,10)

    -- Hotkey = the saved shortcut that shows/hides the menu (editable in Settings)
    local Win={Tabs={},Open=true,Gui=gui,Hotkey={key=Enum.KeyCode.RightShift,mods={}}}

    local function selectTab(tab)
        for _,t in ipairs(Win.Tabs) do
            local on=(t==tab)
            t.page.Visible=on
            tween(t.btn,0.15,{BackgroundColor3=on and Theme.cyan or Theme.navy2})
            t.btn.TextColor3=on and Theme.navy or Theme.white
            t.btn.TextStrokeTransparency=on and 1 or 0.55
        end
    end

    function Win:Toggle(v)
        if v==nil then v=not self.Open end
        self.Open=v
        if v then
            Main.Visible=true
            tween(scale,0.35,{Scale=1},Enum.EasingStyle.Back)
        else
            tween(scale,0.2,{Scale=0},Enum.EasingStyle.Quad,Enum.EasingDirection.In)
            task.delay(0.22,function() if not self.Open then Main.Visible=false end end)
        end
    end

    function Win:Destroy()
        if opts.OnClose then pcall(opts.OnClose) end
        gui:Destroy()
    end

    closeBtn.MouseButton1Click:Connect(function() Win:Destroy() end)
    minBtn.MouseButton1Click:Connect(function() Win:Toggle(false) end)

    -- floating open/close button (works on phones too)
    local fab=make("TextButton",{
        Position=UDim2.new(0,12,0.5,-70),Size=UDim2.fromOffset(46,46),BackgroundColor3=Theme.white,Text="K24",
        Font=Enum.Font.FredokaOne,TextSize=15,TextColor3=Theme.white,AutoButtonColor=true,BorderSizePixel=0,ZIndex=40,
    },gui)
    round(fab,23);stroke(fab,Theme.navy,3);styleText(fab)
    make("UIGradient",{Color=ColorSequence.new(Color3.fromRGB(110,200,255),Color3.fromRGB(30,110,235)),Rotation=90},fab)
    fab.MouseButton1Click:Connect(function() Win:Toggle() end)
    Win.Fab=fab

    -- keyboard shortcut (PC). The shortcut itself can be changed from Settings.
    Bind(UIS.InputBegan,function(i,gp)
        if gp or KB.listening or os.clock()-KB.stamp<0.3 then return end
        if i.UserInputType~=Enum.UserInputType.Keyboard then return end
        if BindMatches(Win.Hotkey,i.KeyCode) then Win:Toggle() end
    end)

    ------------------------------------------------------------
    -- Tabs and elements
    ------------------------------------------------------------
    function Win:CreateTab(name)
        local btn=make("TextButton",{
            Text=name,Size=UDim2.new(1,0,0,36),BackgroundColor3=Theme.navy2,AutoButtonColor=false,
            Font=Enum.Font.FredokaOne,TextSize=16,TextColor3=Theme.white,BorderSizePixel=0,LayoutOrder=#Win.Tabs+1,
        },TabList)
        round(btn,8);stroke(btn,Theme.cyan,1.5,0.6);styleText(btn)

        local page=make("ScrollingFrame",{
            Visible=false,BackgroundTransparency=1,BorderSizePixel=0,Size=UDim2.fromScale(1,1),ScrollBarThickness=4,
            ScrollBarImageColor3=Theme.cyan,CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,
        },Content)
        make("UIListLayout",{Padding=UDim.new(0,8),SortOrder=Enum.SortOrder.LayoutOrder},page)
        make("UIPadding",{PaddingTop=UDim.new(0,10),PaddingLeft=UDim.new(0,10),PaddingRight=UDim.new(0,14),PaddingBottom=UDim.new(0,10)},page)

        local tab={page=page,btn=btn,order=0}
        table.insert(Win.Tabs,tab)
        btn.MouseButton1Click:Connect(function() selectTab(tab) end)
        if #Win.Tabs==1 then selectTab(tab) end

        local function nextOrder() tab.order=tab.order+1;return tab.order end

        local function Row(h)
            local f=make("Frame",{
                Size=UDim2.new(1,0,0,h),BackgroundColor3=Theme.navy2,BackgroundTransparency=0.1,BorderSizePixel=0,LayoutOrder=nextOrder(),
            },page)
            round(f,8);stroke(f,Theme.cyan,1.5,0.55)
            return f
        end
        local function RowLabel(parent,text,w)
            local l=make("TextLabel",{
                BackgroundTransparency=1,Position=UDim2.fromOffset(12,0),Size=w or UDim2.new(1,-70,0,40),Font=Enum.Font.GothamBold,
                Text=text,TextSize=14,TextColor3=Theme.white,TextXAlignment=Enum.TextXAlignment.Left,TextTruncate=Enum.TextTruncate.AtEnd,
            },parent)
            styleText(l)
            return l
        end

        function tab:CreateSection(text)
            local f=make("Frame",{Size=UDim2.new(1,0,0,26),BackgroundTransparency=1,LayoutOrder=nextOrder()},page)
            local l=make("TextLabel",{
                BackgroundTransparency=1,Size=UDim2.new(1,0,1,-4),Font=Enum.Font.FredokaOne,Text=string.upper(text),TextSize=15,
                TextColor3=Color3.fromRGB(170,230,255),TextXAlignment=Enum.TextXAlignment.Left,
            },f)
            styleText(l)
            make("Frame",{Position=UDim2.new(0,0,1,-2),Size=UDim2.new(1,0,0,2),BackgroundColor3=Theme.cyan,BackgroundTransparency=0.45,BorderSizePixel=0},f)
        end

        function tab:CreateLabel(text)
            local row=Row(34)
            local l=RowLabel(row,text,UDim2.new(1,-24,1,0))
            local obj={}
            function obj:Set(t) l.Text=tostring(t) end
            return obj
        end

        function tab:CreateButton(o)
            local b=make("TextButton",{
                Text=o.Name,Size=UDim2.new(1,0,0,38),BackgroundColor3=Theme.blue,AutoButtonColor=false,Font=Enum.Font.GothamBold,
                TextSize=14,TextColor3=Theme.white,BorderSizePixel=0,LayoutOrder=nextOrder(),
            },page)
            round(b,8);stroke(b,Theme.navy,2);styleText(b)
            make("UIGradient",{Color=ColorSequence.new(Theme.white,Color3.fromRGB(150,175,235)),Rotation=90},b)
            b.MouseEnter:Connect(function() tween(b,0.12,{BackgroundColor3=Color3.fromRGB(80,170,255)}) end)
            b.MouseLeave:Connect(function() tween(b,0.12,{BackgroundColor3=Theme.blue}) end)
            b.MouseButton1Click:Connect(function()
                b.BackgroundColor3=Theme.cyan
                tween(b,0.25,{BackgroundColor3=Theme.blue})
                if o.Notify~=false then UI:Notify({Title=o.Name,Content="Action started.",Duration=5}) end
                safe(o.Callback)
            end)
        end

        function tab:CreateToggle(o)
            local row=Row(40)
            RowLabel(row,o.Name)
            local sw=make("Frame",{Size=UDim2.fromOffset(46,24),Position=UDim2.new(1,-58,0.5,-12),BackgroundColor3=Theme.off,BorderSizePixel=0},row)
            round(sw,12);stroke(sw,Theme.navy,1.5)
            local knob=make("Frame",{Size=UDim2.fromOffset(18,18),Position=UDim2.fromOffset(3,3),BackgroundColor3=Theme.white,BorderSizePixel=0},sw)
            round(knob,9)
            local hit=make("TextButton",{Text="",BackgroundTransparency=1,Size=UDim2.fromScale(1,1),ZIndex=3},row)
            local state=o.CurrentValue and true or false
            local function render()
                tween(sw,0.15,{BackgroundColor3=state and Theme.on or Theme.off})
                tween(knob,0.15,{Position=state and UDim2.fromOffset(25,3) or UDim2.fromOffset(3,3)})
            end
            render()
            local obj={}
            function obj:Set(v)
                v=v and true or false
                if v==state then return end
                state=v;render()
                if o.Notify~=false then UI:Notify({Title=o.Name,Content=state and "Enabled." or "Disabled.",Duration=5}) end
                safe(o.Callback,v)
            end
            hit.MouseButton1Click:Connect(function() obj:Set(not state) end)
