        end

        function tab:CreateSlider(o)
            local row=Row(56)
            RowLabel(row,o.Name,UDim2.new(1,-100,0,32))
            local min,max=o.Range[1],o.Range[2]
            local inc=o.Increment or 1
            local suffix=o.Suffix or ""
            local value=o.CurrentValue or min
            local val=make("TextLabel",{
                BackgroundTransparency=1,Position=UDim2.new(1,-110,0,0),Size=UDim2.fromOffset(98,32),Font=Enum.Font.GothamBold,
                TextSize=13,TextColor3=Theme.cyan,TextXAlignment=Enum.TextXAlignment.Right,Text="",
            },row)
            styleText(val)
            local track=make("Frame",{Position=UDim2.new(0,12,0,38),Size=UDim2.new(1,-24,0,8),BackgroundColor3=Theme.off,BorderSizePixel=0},row)
            round(track,4)
            local fill=make("Frame",{Size=UDim2.fromScale(0,1),BackgroundColor3=Theme.cyan,BorderSizePixel=0},track)
            round(fill,4)
            local knob=make("Frame",{
                AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.fromScale(0,0.5),Size=UDim2.fromOffset(16,16),
                BackgroundColor3=Theme.white,BorderSizePixel=0,ZIndex=2,
            },track)
            round(knob,8);stroke(knob,Theme.navy,2)
            local hit=make("TextButton",{Text="",BackgroundTransparency=1,Position=UDim2.new(0,6,0,28),Size=UDim2.new(1,-12,0,28),ZIndex=3},row)
            local function render()
                local r=(value-min)/(max-min)
                fill.Size=UDim2.fromScale(r,1)
                knob.Position=UDim2.fromScale(r,0.5)
                val.Text=tostring(value)..suffix
            end
            render()
            local function fromX(x,fire)
                local r=math.clamp((x-track.AbsolutePosition.X)/math.max(1,track.AbsoluteSize.X),0,1)
                local v=min+r*(max-min)
                v=math.floor((v-min)/inc+0.5)*inc+min
                v=math.clamp(v,min,max)
                if v~=value then value=v;render();if fire~=false then safe(o.Callback,v) end end
            end
            local dragging=false
            hit.InputBegan:Connect(function(i)
                if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then
                    dragging=true;fromX(i.Position.X)
                end
            end)
            Bind(UIS.InputChanged,function(i)
                if dragging and (i.UserInputType==Enum.UserInputType.MouseMovement or i.UserInputType==Enum.UserInputType.Touch) then
                    fromX(i.Position.X)
                end
            end)
            Bind(UIS.InputEnded,function(i)
                if (i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch) and dragging then
                    dragging=false
                    if o.Notify~=false then UI:Notify({Title=o.Name,Content="Value: "..tostring(value)..suffix,Duration=5}) end
                end
            end)
            local obj={}
            function obj:Set(v) value=math.clamp(v,min,max);render();safe(o.Callback,value) end
            return obj
        end

        function tab:CreateDropdown(o)
            local row=Row(40);row.ClipsDescendants=true
            RowLabel(row,o.Name,UDim2.new(0.4,0,0,40))
            local head=make("TextButton",{Text="",BackgroundTransparency=1,Size=UDim2.new(1,0,0,40),ZIndex=3},row)
            local cur=make("TextLabel",{
                BackgroundTransparency=1,Position=UDim2.new(0.4,0,0,0),Size=UDim2.new(0.6,-34,0,40),Font=Enum.Font.GothamBold,
                TextSize=13,TextColor3=Theme.cyan,TextXAlignment=Enum.TextXAlignment.Right,TextTruncate=Enum.TextTruncate.AtEnd,Text="None",
            },row)
            local arrow=make("TextLabel",{
                BackgroundTransparency=1,Position=UDim2.new(1,-28,0,0),Size=UDim2.fromOffset(20,40),Font=Enum.Font.GothamBold,
                TextSize=12,TextColor3=Theme.white,Text="▼",
            },row)
            local list=make("ScrollingFrame",{
                BackgroundTransparency=1,BorderSizePixel=0,Position=UDim2.fromOffset(8,46),Size=UDim2.new(1,-16,0,0),
                ScrollBarThickness=3,CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,
            },row)
            make("UIListLayout",{Padding=UDim.new(0,4),SortOrder=Enum.SortOrder.LayoutOrder},list)
            local options=o.Options or {}
            local selected=o.CurrentOption and o.CurrentOption[1] or nil
            if selected then cur.Text=selected end
            local open=false
            local function listH() return math.min(#options,5)*32 end
            local function applySize()
                row.Size=UDim2.new(1,0,0,open and (54+listH()) or 40)
                list.Size=UDim2.new(1,-16,0,listH())
                arrow.Text=open and "▲" or "▼"
            end
            local function rebuild()
                for _,c in ipairs(list:GetChildren()) do if c:IsA("TextButton") then c:Destroy() end end
                for i,name in ipairs(options) do
                    local b=make("TextButton",{
                        Text=name,Size=UDim2.new(1,-6,0,28),BackgroundColor3=Theme.blue,AutoButtonColor=true,Font=Enum.Font.GothamBold,
                        TextSize=13,TextColor3=Theme.white,BorderSizePixel=0,LayoutOrder=i,
                    },list)
                    round(b,6);stroke(b,Theme.navy,1.5);styleText(b)
                    b.MouseButton1Click:Connect(function()
                        selected=name;cur.Text=name;open=false;applySize()
                        if o.Notify~=false then UI:Notify({Title=o.Name,Content="Selected: "..tostring(name),Duration=5}) end
                        safe(o.Callback,{name})
                    end)
                end
                if selected and not table.find(options,selected) then selected=nil;cur.Text="None" end
                applySize()
            end
            rebuild()
            head.MouseButton1Click:Connect(function() open=not open;applySize() end)
            local obj={}
            function obj:Refresh(newOptions) options=newOptions or {};rebuild() end
            return obj
        end

        -- Keybind editor (PC). Click it, then press the new shortcut.
        --  * Optional modifiers: Shift, Ctrl, Alt (any combination)
        --  * Not allowed as the main key: W A S D Q E F and Windows
        --  * Esc cancels. A modifier pressed and released alone is saved as the key itself.
        function tab:CreateKeybind(o)
            local row=Row(40)
            RowLabel(row,o.Name,UDim2.new(0.45,0,0,40))
            local btn=make("TextButton",{
                Position=UDim2.new(0.45,0,0.5,-15),Size=UDim2.new(0.55,-10,0,30),BackgroundColor3=Theme.blue,AutoButtonColor=false,
                Font=Enum.Font.GothamBold,TextSize=13,TextColor3=Theme.white,BorderSizePixel=0,Text="",
            },row)
            round(btn,8);stroke(btn,Theme.navy,2);styleText(btn)
            local bind={key=o.Key,mods=o.Mods or {}}
            local listening=false
            local pendingMod
            local function render()
                btn.Text=listening and "Press keys...  (Esc = cancel)" or BindText(bind)
            end
            local function stop()
                listening=false;KB.listening=false;KB.stamp=os.clock();pendingMod=nil
                render()
            end
            local function commit(key,mods)
                bind={key=key,mods=mods}
                stop()
                if o.Notify~=false then UI:Notify({Title=o.Name,Content="Shortcut: "..BindText(bind),Duration=5}) end
                safe(o.Callback,bind)
            end
            render()
            btn.MouseButton1Click:Connect(function()
                if listening then stop() return end
                listening=true;KB.listening=true;pendingMod=nil
                render()
            end)
            Bind(UIS.InputBegan,function(i)
                if not listening or i.UserInputType~=Enum.UserInputType.Keyboard then return end
                local kc=i.KeyCode
                if kc==Enum.KeyCode.Unknown then return end
                if kc==Enum.KeyCode.Escape then stop() return end
                if BLOCKED[kc] then
                    btn.Text="Not allowed: "..kc.Name
                    return
                end
                if ModOfKey(kc) then pendingMod=kc return end
                commit(kc,HeldMods())
            end)
            Bind(UIS.InputEnded,function(i)
                if not listening or i.UserInputType~=Enum.UserInputType.Keyboard then return end
                if pendingMod and i.KeyCode==pendingMod then commit(pendingMod,{}) end
            end)
            local obj={}
            function obj:Get() return bind end
            return obj
        end

        function tab:CreateColorPicker(o)
            local row=Row(40);row.ClipsDescendants=true
            RowLabel(row,o.Name)
            local swatch=make("Frame",{Position=UDim2.new(1,-52,0,9),Size=UDim2.fromOffset(40,22),BackgroundColor3=o.Color or Theme.white,BorderSizePixel=0},row)
            round(swatch,6);stroke(swatch,Theme.white,2)
            local head=make("TextButton",{Text="",BackgroundTransparency=1,Size=UDim2.new(1,0,0,40),ZIndex=3},row)
            local pal=make("Frame",{BackgroundTransparency=1,Position=UDim2.fromOffset(8,46),Size=UDim2.new(1,-16,0,72)},row)
            make("UIGridLayout",{CellSize=UDim2.fromOffset(30,30),CellPadding=UDim2.fromOffset(6,6),SortOrder=Enum.SortOrder.LayoutOrder},pal)
            local colors={
                {255,50,50},{255,150,40},{255,230,60},{140,240,60},{50,220,110},{60,230,255},
                {50,120,255},{150,80,255},{255,70,200},{255,150,190},{255,255,255},{150,150,160},
            }
            for i,c in ipairs(colors) do
                local col=Color3.fromRGB(c[1],c[2],c[3])
                local b=make("TextButton",{Text="",BackgroundColor3=col,BorderSizePixel=0,LayoutOrder=i,AutoButtonColor=true},pal)
                round(b,6);stroke(b,Theme.navy,1.5)
                b.MouseButton1Click:Connect(function()
                    swatch.BackgroundColor3=col
                    if o.Notify~=false then UI:Notify({Title=o.Name,Content="Color updated.",Duration=5}) end
                    safe(o.Callback,col)
                end)
            end
            local open=false
            head.MouseButton1Click:Connect(function()
                open=not open
                row.Size=UDim2.new(1,0,0,open and 126 or 40)
            end)
        end

        return tab
    end

    -- opening animation
    Win:Toggle(true)
    return Win
end

local RF=UI

