local Unload -- forward declaration (defined at the bottom)
local Win=RF:CreateWindow({Name="FATAL FLOORS HUB",OnClose=function() if Unload then Unload() end end})
local TMain=Win:CreateTab("Main")
local TESP=Win:CreateTab("ESP")
local TCurr=Win:CreateTab("Currency")
