local TItems=Win:CreateTab("Items")

-- Items confirmed in the supplied game place. Names are matched exactly (case-insensitive).
-- Removed: Copper Ore, Coal, Silver, Diamond, Obsidian, Ruby and Sapphire.
local ORES={"Iron Ore","Jade Ore","Amber Ore","Gold Ore","Amethyst Ore","Reviver","Giant Egg","Ham","Gold Key","Carrot"}
local CURR={"coin","coins","cash","money","gem","gems","token","tokens","buck","bucks","currency","dollar"}
local SELL_KW={"sellstation","sell_station","sell station","sellingstation","cashier","store"}

local ITEM_BY_LOWER={}
for _,n in ipairs(ORES) do ITEM_BY_LOWER[string.lower(n)]=n end

local C={
    cur=false,ref=true,ret=true,
    mESP=false,oESP=false,pESP=false,sESP=false,
    mCol=Color3.fromRGB(255,50,50),
    oCol=Color3.fromRGB(50,200,255),
    pCol=Color3.fromRGB(255,255,50),
    sCol=Color3.new(1,1,1),
    dist=true,names=true,
    noclip=false,fly=false,afk=false,ij=false,
    espDist=2000,   -- ESP is only drawn inside this distance (studs)
    espMax=8,       -- max objects WITH OUTLINE per category (Roblox only renders 31 Highlights at once)
    espLabelMax=40, -- max objects WITH NAME LABEL per category (labels have no render limit)
    espRate=0.25,   -- seconds between ESP updates
    avoid=true,     -- skip ores that have monsters nearby
    avoidDist=35,
    platDist=30,    -- max distance between the platform we stand on and the ore (studs)
    fb=false,       -- Fullbright
    lockSpd=true,   -- keep the WalkSpeed/JumpPower picked in the menu even if the game changes it
    instant=false,  -- instant ProximityPrompts
    shiftlockEnabled=false,
    shiftlock=false,
    autoFarm=false,autoBring=false,
    manualDelay=0.12,farmDelay=0.12,bringDelay=0.12,
    farmItems={},espItems={},
    spd=nil,jmp=nil
}
for _,n in ipairs(ORES) do C.farmItems[n]=true;C.espItems[n]=true end

local SLbl,CLbl

----------------------------------------------------------------
-- MAP INDEX (scanned ONCE, then kept up to date with events)
----------------------------------------------------------------
local OreSet,CurrSet,SellSet,MonSet,Spawns,ShardSet={}, {}, {}, {}, {}, {}
local PartCache=setmetatable({}, {__mode="k"})
local IndexReady=false

local function OreName(lname)
    return ITEM_BY_LOWER[string.lower(lname or "")]
end

local function SameAncestor(set,o,val)
    -- avoids registering the same object twice (model + child parts with the same name)
    local a=o.Parent
    while a and a~=WS do
        if set[a] and (val==nil or set[a]==val) then return true end
        a=a.Parent
    end
    return false
end

-- INSTANT PROXIMITY PROMPTS (HoldDuration = 0)
local Prompts={}
local OrigHold=setmetatable({}, {__mode="k"})
local HookedP=setmetatable({}, {__mode="k"})
local function ApplyInstant(p)
    if C.instant then
        if OrigHold[p]==nil then OrigHold[p]=p.HoldDuration end
        if p.HoldDuration~=0 then p.HoldDuration=0 end
        if not HookedP[p] then
            HookedP[p]=true
            -- if the game tries to restore the hold time, set it back to 0
            Bind(p:GetPropertyChangedSignal("HoldDuration"),function()
                if C.instant and p.HoldDuration~=0 then p.HoldDuration=0 end
            end)
        end
    elseif OrigHold[p]~=nil then
        p.HoldDuration=OrigHold[p]
        OrigHold[p]=nil
    end
end
local function SetInstant(v)
    C.instant=v
    for p in pairs(Prompts) do
        if p.Parent then pcall(ApplyInstant,p) else Prompts[p]=nil end
    end
end

local function Classify(o)
    if o:IsA("ProximityPrompt") then
        Prompts[o]=true
        if C.instant then pcall(ApplyInstant,o) end
        return
    end
    if o:IsA("SpawnLocation") then Spawns[o]=true;return end
    if o:IsA("UnionOperation") and o.Name=="Shard" then
        ShardSet[o]=true
    end
    -- RoofMonster in this place is not guaranteed to expose a Humanoid.
    -- Register the named model/part directly so Monster ESP can still track it.
    if (o:IsA("Model") or o:IsA("BasePart")) and string.lower(o.Name)=="roofmonster" then
        MonSet[o]=true
    end
    if o:IsA("Humanoid") then
        local m=o.Parent
        if m and m:IsA("Model") and not PL:GetPlayerFromCharacter(m) then MonSet[m]=true end
        return
    end
    if not (o:IsA("BasePart") or o:IsA("Model") or o:IsA("Tool")) then return end
    local ln=string.lower(o.Name)
    local on=OreName(ln)
    if on and not SameAncestor(OreSet,o,on) then OreSet[o]=on end
    for _,k in ipairs(CURR) do
        if string.find(ln,k,1,true) then
            if not SameAncestor(CurrSet,o) then CurrSet[o]=true end
            break
        end
    end
    for _,k in ipairs(SELL_KW) do
        if string.find(ln,k,1,true) then SellSet[o]=true;break end
    end
end

local RemESP -- forward declaration
local function Unclassify(o)
    OreSet[o]=nil;CurrSet[o]=nil;SellSet[o]=nil;MonSet[o]=nil;ShardSet[o]=nil;PartCache[o]=nil;Prompts[o]=nil;Spawns[o]=nil
    RemESP(o)
end

task.spawn(function()
    Bind(WS.DescendantAdded,function(o) pcall(Classify,o) end)
    Bind(WS.DescendantRemoving,function(o) pcall(Unclassify,o) end)
    local list=WS:GetDescendants()
    for i,o in ipairs(list) do
        pcall(Classify,o)
        if i%1500==0 then
            task.wait() -- spread the scan so the game does not freeze
            if not Alive then return end
        end
    end
    IndexReady=true
end)

local function WaitIndex()
    while not IndexReady and Alive do task.wait(0.2) end
end

----------------------------------------------------------------
-- HELPERS
----------------------------------------------------------------
local function Root()
    local ch=LP.Character
    return ch and ch:FindFirstChild("HumanoidRootPart")
end

local function IsAlive()
    local ch=LP.Character
    local h=ch and ch:FindFirstChildOfClass("Humanoid")
    return h~=nil and h.Health>0 and Root()~=nil
end

local function Running()
    return Alive and IsAlive()
end

local function GetPos(o)
    if not o or not o.Parent then return nil end
    if o:IsA("Model") then
        local ok,cf=pcall(function() return o:GetPivot() end)
        return ok and cf.Position or nil
    elseif o:IsA("BasePart") then
        return o.Position
    elseif o:IsA("Tool") then
        local part=o:FindFirstChildWhichIsA("BasePart",true)
        return part and part.Position or nil
    end
    return nil
end

local function PartOf(o)
    if o:IsA("BasePart") then return o end
    local c=PartCache[o]
    if c and c.Parent then return c end
    c=nil
    if o:IsA("Model") then
        c=o.PrimaryPart or o:FindFirstChild("HumanoidRootPart") or o:FindFirstChildWhichIsA("BasePart",true)
    elseif o:IsA("Tool") then
        c=o:FindFirstChildWhichIsA("BasePart",true)
    end
    PartCache[o]=c
    return c
end

-- ProximityPrompt helper: send E when possible, then use supported prompt fallbacks.
local VIM
local function FindOrePrompt(o)
    if not o then return nil end
    if o:IsA("ProximityPrompt") then return o end
    local candidates,seen={},{}
    local function scan(root)
        if not root then return end
        for _,d in ipairs(root:GetDescendants()) do
            if d:IsA("ProximityPrompt") and d.Enabled and not seen[d] then
                seen[d]=true
                local parent=d.Parent
                local p=(parent and parent:IsA("Attachment") and parent.WorldPosition)
                    or (parent and parent:IsA("BasePart") and parent.Position)
                local target=GetPos(o)
                candidates[#candidates+1]={prompt=d,distance=(p and target and (p-target).Magnitude) or math.huge}
            end
        end
    end
    scan(o)
    -- Some pickups are named BaseParts while their prompt is a sibling under the containing Model.
    local ancestor=o.Parent
    while ancestor and ancestor~=WS do
        if ancestor:IsA("Model") then scan(ancestor) end
        ancestor=ancestor.Parent
    end
    table.sort(candidates,function(a,b) return a.distance<b.distance end)
    return candidates[1] and candidates[1].prompt or nil
end

local function FireSpecificPrompt(prompt)
    if not prompt or not prompt.Parent or not prompt.Enabled then return false end

    local root=Root()
    local parent=prompt.Parent
    local promptPos
    if parent and parent:IsA("Attachment") then
        promptPos=parent.WorldPosition
    elseif parent and parent:IsA("BasePart") then
        promptPos=parent.Position
    end
    if root and promptPos and (root.Position-promptPos).Magnitude>prompt.MaxActivationDistance+2 then
        return false
    end

    -- InputHoldBegin/End uses the prompt's configured input mapping (keyboard,
    -- gamepad and touch UI) instead of hard-coding the E key.
    local ok=pcall(function()
        prompt:InputHoldBegin()
        task.wait(math.max(0.05,prompt.HoldDuration))
        prompt:InputHoldEnd()
    end)
    if ok then return true end

    if VIM then
        local key
        if UIS.GamepadEnabled and prompt.GamepadKeyCode~=Enum.KeyCode.Unknown then
            key=prompt.GamepadKeyCode
        else
            key=prompt.KeyboardKeyCode
        end
        if key and key~=Enum.KeyCode.Unknown then
            local sent=pcall(function()
                VIM:SendKeyEvent(true,key,false,game)
                task.wait(math.max(0.08,prompt.HoldDuration))
                VIM:SendKeyEvent(false,key,false,game)
            end)
            if sent then return true end
        end
    end

    if type(fireproximityprompt)=="function" then
        local fired=pcall(fireproximityprompt,prompt)
        if fired then return true end
    end
    return false
end

local function FirePx(o)
    return FireSpecificPrompt(FindOrePrompt(o))
end
local function MonsterNear(pos,radius)
    for m in pairs(MonSet) do
        if m.Parent then
            local p=GetPos(m)
            if p and (p-pos).Magnitude<=radius then return true end
        else
            MonSet[m]=nil
        end
    end
    return false
end

----------------------------------------------------------------
-- SAFE TELEPORT
--  * TpTo(): moves you, zeroes the velocity for a few frames (no fall damage) and remembers the spot
--  * SafeTp(): used for spawn / sell station / currency (known safe places)
--  * OreTp(): used for collectible items (Manual Collect / Auto Farm / Auto Bring). It never teleports "to the
--    ore". It looks for the nearest solid PLATFORM around the ore (raycasts that only count solid,
--    walkable, non-hazard surfaces with head room) and teleports you ON TOP of it. If there is no
--    platform within "Max Platform Distance", the ore is skipped instead of risking a fall.
--  * Anti-void: while farming, if you fall below the map you are put back on your last safe spot.
----------------------------------------------------------------
local RayP=RaycastParams.new()
RayP.FilterType=Enum.RaycastFilterType.Exclude
RayP.RespectCanCollide=true -- ignore invisible / non-solid parts (they made you fall through)
RayP.IgnoreWater=true
local LastSafe

local function BuildIgnore(extra)
    local ignore={}
    if LP.Character then ignore[#ignore+1]=LP.Character end
    for _,p in ipairs(PL:GetPlayers()) do if p.Character then ignore[#ignore+1]=p.Character end end
    for m in pairs(MonSet) do if m.Parent then ignore[#ignore+1]=m end end
    if extra and extra.Parent then ignore[#ignore+1]=extra end
    return ignore
end

local function TpTo(target,settleDelay)
    local r=Root()
    if not r then return false end
    r.AssemblyLinearVelocity=Vector3.zero
    r.AssemblyAngularVelocity=Vector3.zero
    r.CFrame=CFrame.new(target)
    for _=1,6 do
        RS.Heartbeat:Wait()
        if not r.Parent then return false end
        r.AssemblyLinearVelocity=Vector3.zero
    end
    task.wait(math.max(0,settleDelay==nil and 0.08 or settleDelay))
    if IsAlive() then LastSafe=target;return true end
    return false
end

local function SafeTp(pos)
    if not Alive or not pos or not IsAlive() then return false end
    RayP.FilterDescendantsInstances=BuildIgnore()
    local hit=WS:Raycast(pos+Vector3.new(0,4,0),Vector3.new(0,-40,0),RayP)
    local target=hit and (hit.Position+Vector3.new(0,3.2,0)) or (pos+Vector3.new(0,3.5,0))
    return TpTo(target)
end

local DIRS={}
for k=0,7 do
    local a=k*math.pi/4
    DIRS[#DIRS+1]=Vector3.new(math.cos(a),0,math.sin(a))
end
local RADII={0,3,6,10,15,22}
local BAD_SURF={"kill","lava","death","void","damage","acid","spike","hazard"}
local function NameBad(n)
    n=string.lower(n)
    for _,k in ipairs(BAD_SURF) do
        if string.find(n,k,1,true) then return true end
    end
    return false
end
local function BadSurface(inst)
    if NameBad(inst.Name) then return true end
    local p=inst.Parent
    return p~=nil and p~=WS and NameBad(p.Name)
end

-- Returns the standing position (on top of the nearest safe platform) or nil
local function FindStand(opos,oreObj,maxDist)
    RayP.FilterDescendantsInstances=BuildIgnore(oreObj)
    local voidY=WS.FallenPartsDestroyHeight
    local best,bestD
    local heights={4,math.max(10,maxDist)}
    for _,hgt in ipairs(heights) do
        for _,rad in ipairs(RADII) do
            local nd=(rad==0) and 1 or #DIRS
            for k=1,nd do
                local off=(rad==0) and Vector3.zero or DIRS[k]*rad
                local origin=Vector3.new(opos.X+off.X,opos.Y+hgt,opos.Z+off.Z)
                local hit=WS:Raycast(origin,Vector3.new(0,-(hgt+60),0),RayP)
                if hit and hit.Normal.Y>=0.6 and not BadSurface(hit.Instance) then
                    local stand=hit.Position+Vector3.new(0,3.2,0)
                    local d=(stand-opos).Magnitude
                    if d<=maxDist and stand.Y>voidY+25 and (not bestD or d<bestD) then
                        -- head room: nothing solid right above the spot
                        if not WS:Raycast(hit.Position+Vector3.new(0,0.3,0),Vector3.new(0,5.5,0),RayP) then
                            best,bestD=stand,d
                        end
                    end
                end
            end
        end
        if best then break end
    end
    return best
end

-- returns "ok", "skip" (no safe platform near the ore) or "dead"
local function OreTp(o,pos,settleDelay)
    if not Alive or not IsAlive() then return "dead" end
    local prompt=FindOrePrompt(o)
    local maxStand=C.platDist
    if prompt then maxStand=math.min(maxStand,math.max(4,prompt.MaxActivationDistance-1)) end

    -- Giant Egg is special: when its own surface is solid, stand directly on
    -- its upper face. The root is placed just above the surface, not inside it.
    if OreSet[o]=="Giant Egg" then
        local eggPart=PartOf(o)
        if eggPart and eggPart:IsA("BasePart") and eggPart.CanCollide
            and not BadSurface(eggPart) then
            local topY=eggPart.Position.Y + eggPart.Size.Y*0.5
            local stand=Vector3.new(eggPart.Position.X,topY+3.15,eggPart.Position.Z)
            local clear=not WS:Raycast(Vector3.new(eggPart.Position.X,topY+0.35,eggPart.Position.Z),Vector3.new(0,5.5,0),RayP)
            if clear and topY>WS.FallenPartsDestroyHeight+25 then
                if TpTo(stand,settleDelay) then return "ok" end
                return "dead"
            end
        end
        -- If the egg is non-solid or unsafe, use a nearby walkable platform.
        maxStand=math.min(maxStand,8)
    end

    local stand=FindStand(pos,o,maxStand)
    if not stand then return "skip" end
    if TpTo(stand,settleDelay) then return "ok" end
    return "dead"
end

-- ANTI-VOID
Bind(RS.Heartbeat,function()
    if not LastSafe then return end
    local ch=LP.Character
    local r=ch and ch:FindFirstChild("HumanoidRootPart")
    local h=ch and ch:FindFirstChildOfClass("Humanoid")
    if not r or not h or h.Health<=0 then return end
