    if y<WS.FallenPartsDestroyHeight+100 or y<LastSafe.Y-200 then
        r.AssemblyLinearVelocity=Vector3.zero
        r.CFrame=CFrame.new(LastSafe)
    end
end)

-- Farthest matching item of one type (used by Manual Collect)
local IsWithinBaseRange,GetSpawn
local function NearestOre(name,taken)
    local r=Root()
    local spawn=GetSpawn()
    local rp=(spawn and spawn.Position) or (r and r.Position)
    local cand={}
    for o,n in pairs(OreSet) do
        if n==name then
            if o.Parent then
                local skip=false
                for _,t in ipairs(taken) do if t==o then skip=true;break end end
                if not skip and not MonSet[o] then
                    local p=GetPos(o)
                    if p and IsWithinBaseRange(p) then
                        cand[#cand+1]={o=o,p=p,d=rp and (p-rp).Magnitude or 0}
                    end
                end
            else
                OreSet[o]=nil
            end
        end
    end
    table.sort(cand,function(a,b) return a.d>b.d end)
    for _,c in ipairs(cand) do
        if not C.avoid or not MonsterNear(c.p,C.avoidDist) then return c.o end
    end
end

-- FARTHEST selected item from a reference point.
-- minDist skips ores whose HORIZONTAL distance to the reference is smaller (Auto Bring uses it so it
-- never grabs the ores that are around the spawn).
local Bad={} -- [ore]=time until we ignore it (failed or already handled)
local function FarthestOre(refPos,taken,minDist)
    local now=os.clock()
    local voidY=WS.FallenPartsDestroyHeight
    local cand={}
    for o,n in pairs(OreSet) do
        if o.Parent then
            if C.farmItems[n]~=false and not MonSet[o] and not (Bad[o] and Bad[o]>now) then
                local skip=false
                for _,t in ipairs(taken) do if t==o then skip=true;break end end
                if not skip then
                    local p=GetPos(o)
                    if p and p.Y>voidY+5 and IsWithinBaseRange(p) then
                        local d=(p-refPos).Magnitude
                        local flat=Vector3.new(p.X-refPos.X,0,p.Z-refPos.Z).Magnitude
                        if flat>=(minDist or 0) then cand[#cand+1]={o=o,p=p,d=d} end
                    end
                end
            end
        else
            OreSet[o]=nil
        end
    end
    table.sort(cand,function(a,b) return a.d>b.d end)
    for _,c in ipairs(cand) do
        if not C.avoid or not MonsterNear(c.p,C.avoidDist) then return c.o end
    end
end

local SellCache
local function FindSell()
    if SellCache and SellCache.Parent then return SellCache end
    local r=Root()
    local rp=r and r.Position
    local best,bd,bestPrompt
    for o in pairs(SellSet) do
        if o.Parent then
            local p=GetPos(o)
            if p then
                local has=false
                for _,d in ipairs(o:GetDescendants()) do
                    if d:IsA("ProximityPrompt") then has=true;break end
                end
                local d=rp and (p-rp).Magnitude or 0
                -- prefer the one with a ProximityPrompt, then the nearest
                if not best or (has and not bestPrompt) or (has==bestPrompt and d<bd) then
                    best,bd,bestPrompt=o,d,has
                end
            end
        end
    end
    SellCache=best
    return best
end

-- The spawn used by "Teleport to Spawn" and as the base-range reference.
-- There is NO hard-coded coordinate: it is the player's RespawnLocation if the game sets one,
-- otherwise the nearest enabled SpawnLocation found in the map. Use Extras > "Show Spawn Position"
-- to see the exact position that is being used.
local SpawnCache
GetSpawn=function()
    if SpawnCache and SpawnCache.Parent then return SpawnCache end
    local rl=LP.RespawnLocation
    if rl and rl.Parent then SpawnCache=rl;return rl end
    local r=Root()
    local rp=r and r.Position
    local best,bd
    for pass=1,2 do
        for o in pairs(Spawns) do
            if o.Parent and (pass==2 or o.Enabled) then
                local d=rp and (o.Position-rp).Magnitude or 0
                if not best or d<bd then best,bd=o,d end
            end
        end
        if best then break end
    end
    SpawnCache=best
    return best
end

-- The base reference is the player's active/nearest SpawnLocation.
-- The allowed collection area is a 1200x1200 stud square and 250 studs vertically.
local ORE_RANGE_X=600
local ORE_RANGE_Z=600
local ORE_RANGE_Y=250
IsWithinBaseRange=function(pos)
    if not pos then return false end
    local spawn=GetSpawn()
    local root=Root()
    local center=spawn and spawn.Position or (root and root.Position)
    if not center then return false end
    local baseCF=spawn and spawn.CFrame or (root and root.CFrame)
    if not baseCF then return false end
    local localPos=baseCF:PointToObjectSpace(pos)
    return math.abs(localPos.X)<=ORE_RANGE_X
        and math.abs(localPos.Z)<=ORE_RANGE_Z
        and math.abs(localPos.Y)<=ORE_RANGE_Y
end

local function EquipTool(t)
    local ch=LP.Character
    local h=ch and ch:FindFirstChildOfClass("Humanoid")
    if h and t and t.Parent then pcall(function() h:EquipTool(t) end);task.wait(0.3) end
end

local function EqBP()
    local bp=LP:FindFirstChild("Backpack");local ch=LP.Character
    if not bp or not ch then return false end
    local h=ch:FindFirstChildOfClass("Humanoid")
    if not h then return false end
    for _,t in ipairs(bp:GetChildren()) do if t:IsA("Tool") then h:EquipTool(t);task.wait(0.4);return true end end
    return false
end

----------------------------------------------------------------
-- WALKSPEED / JUMP (works with JumpPower and with the newer JumpHeight)
----------------------------------------------------------------
local MoveOrig -- original values, restored when the menu is closed
local function ApplySpeed(spd,jmp)
    if spd then C.spd=spd end
    if jmp then C.jmp=jmp end
    local ch=LP.Character
    if not ch then return end
    local h=ch:FindFirstChildOfClass("Humanoid")
    if h then
        if not MoveOrig then MoveOrig={ws=h.WalkSpeed,jp=h.JumpPower,jh=h.JumpHeight} end
        if spd then h.WalkSpeed=spd end
        if jmp then
            if h.UseJumpPower then h.JumpPower=jmp else h.JumpHeight=jmp*jmp/(2*WS.Gravity) end
        end
    end
end

local function RestoreMovement()
    C.spd=nil;C.jmp=nil
    local ch=LP.Character
    local h=ch and ch:FindFirstChildOfClass("Humanoid")
    if h and MoveOrig then
        h.WalkSpeed=MoveOrig.ws
        if h.UseJumpPower then h.JumpPower=MoveOrig.jp else h.JumpHeight=MoveOrig.jh end
    end
end

-- Re-apply speed and jump after respawning
Bind(LP.CharacterAdded,function()
    task.wait(1)
    if Alive and (C.spd or C.jmp) then ApplySpeed(C.spd,C.jmp) end
end)

-- LOCKED WALKSPEED
-- Every rendered frame, after the game's normal update priorities, the selected value is reapplied.
-- change it when you crouch, get hurt, sprint, etc.
local LockHum
local ShiftHum,ShiftOldOffset,ShiftOldMouse
local LOCK_STEP="K24_LockedMovement"
RS:BindToRenderStep(LOCK_STEP,Enum.RenderPriority.Last.Value,function()
    local ch=LP.Character
    local hum=ch and ch:FindFirstChildOfClass("Humanoid")

    if C.shiftlock and hum then
        if ShiftHum~=hum then
            ShiftHum=hum
            ShiftOldOffset=hum.CameraOffset
        end
        local offset=Vector3.new(1.75,0,0)
        if hum.CameraOffset~=offset then hum.CameraOffset=offset end
        if UIS.MouseBehavior~=Enum.MouseBehavior.LockCenter then
            UIS.MouseBehavior=Enum.MouseBehavior.LockCenter
        end
    end

    if not C.lockSpd or (not C.spd and not C.jmp) then return end
    if not hum then LockHum=nil;return end
    if LockHum~=hum then LockHum=hum end

    if C.spd and math.abs(hum.WalkSpeed-C.spd)>0.01 then hum.WalkSpeed=C.spd end
    if C.jmp then
        if hum.UseJumpPower then
            if math.abs(hum.JumpPower-C.jmp)>0.01 then hum.JumpPower=C.jmp end
        else
            local want=C.jmp*C.jmp/(2*WS.Gravity)
            if math.abs(hum.JumpHeight-want)>0.01 then hum.JumpHeight=want end
        end
    end
end)

-- Optional Caps Lock shiftlock. It locks the mouse and offsets the camera to the right.
local function SetShiftLock(v)
    local wasActive=C.shiftlock
    C.shiftlock=v and true or false
    local ch=LP.Character
    local hum=ch and ch:FindFirstChildOfClass("Humanoid")

    if C.shiftlock then
        ShiftHum=hum
        ShiftOldOffset=hum and hum.CameraOffset or Vector3.zero
        ShiftOldMouse=UIS.MouseBehavior
        if hum then hum.CameraOffset=Vector3.new(1.75,0,0) end
        UIS.MouseBehavior=Enum.MouseBehavior.LockCenter
    else
        if wasActive and ShiftHum and ShiftHum.Parent and ShiftOldOffset then
            ShiftHum.CameraOffset=ShiftOldOffset
        end
        if wasActive then
            UIS.MouseBehavior=ShiftOldMouse or Enum.MouseBehavior.Default
        end
        ShiftHum=nil;ShiftOldOffset=nil;ShiftOldMouse=nil
    end
end

Bind(UIS.InputBegan,function(input,gp)
    if gp or KB.listening then return end
    if C.shiftlockEnabled and input.UserInputType==Enum.UserInputType.Keyboard
        and input.KeyCode==Enum.KeyCode.CapsLock then
        SetShiftLock(not C.shiftlock)
        RF:Notify({Title="Shiftlock",Content=C.shiftlock and "Caps Lock: ON" or "Caps Lock: OFF",Duration=5})
    end
end)

Bind(LP.CharacterAdded,function(ch)
    task.wait(0.5)
    if C.shiftlock and Alive then
        local hum=ch:FindFirstChildOfClass("Humanoid")
        if hum then
