end)

----------------------------------------------------------------
-- GRABBING AND DROPPING ITEMS
-- Grab: ProximityPrompt (E on PC / tap on phone).
-- Drop: Q. The script tries, in order: (1) the ContextActionService action bound to Q
-- (this is also what a phone's on-screen drop button uses), (2) a simulated Q key through
-- VirtualInputManager, (3) the executor's keypress(). It checks that the item really left
-- your inventory before moving on.
----------------------------------------------------------------
do
    local ok,v=pcall(function() return game:GetService("VirtualInputManager") end)
    VIM=ok and v or nil
end

local LastInput
Bind(UIS.InputBegan,function(i) LastInput=i end)

-- The supplied game's controls module confirms: Q on keyboard, DPadDown on gamepad.
local function DropViaCAS(key)
    local used=false
    pcall(function()
        for name,info in pairs(CAS:GetAllBoundActionInfo()) do
            for _,it in ipairs(info.inputTypes or {}) do
                if it==key and LastInput then
                    CAS:CallFunction(name,Enum.UserInputState.Begin,LastInput)
                    task.wait(0.05)
                    CAS:CallFunction(name,Enum.UserInputState.End,LastInput)
                    used=true
                    break
                end
            end
            if used then break end
        end
    end)
    return used
end

local function DropViaTouch()
    local pg=LP:FindFirstChildOfClass("PlayerGui")
    if not pg then return false end
    local CollectionService=game:GetService("CollectionService")
    for _,g in ipairs(pg:GetDescendants()) do
        if g:IsA("GuiButton") and g.Visible and g.Active~=false then
            local n=string.lower(g.Name)
            local t=string.lower(g:IsA("TextButton") and g.Text or "")
            local tagged=false
            pcall(function() tagged=CollectionService:HasTag(g,"DropItem") end)
            if tagged or string.find(n,"drop",1,true) or string.find(t,"drop",1,true) then
                local ok=pcall(function() g:Activate() end)
                if ok then return true end
            end
        end
    end
    return false
end

local function DropViaKeyboard()
    if VIM then
        local ok=pcall(function()
            VIM:SendKeyEvent(true,Enum.KeyCode.Q,false,game)
            task.wait(0.07)
            VIM:SendKeyEvent(false,Enum.KeyCode.Q,false,game)
        end)
        if ok then return true end
    end
    if type(keypress)=="function" and type(keyrelease)=="function" then
        local ok=pcall(function() keypress(0x51);task.wait(0.07);keyrelease(0x51) end)
        if ok then return true end
    end
    return false
end

local function DropViaGamepad()
    if VIM then
        local ok=pcall(function()
            VIM:SendGamepadEvent(Enum.UserInputType.Gamepad1,Enum.KeyCode.DPadDown,Enum.UserInputState.Begin)
            task.wait(0.07)
            VIM:SendGamepadEvent(Enum.UserInputType.Gamepad1,Enum.KeyCode.DPadDown,Enum.UserInputState.End)
        end)
        if ok then return true end
        local ok2=pcall(function()
            VIM:SendKeyEvent(true,Enum.KeyCode.DPadDown,false,game)
            task.wait(0.07)
            VIM:SendKeyEvent(false,Enum.KeyCode.DPadDown,false,game)
        end)
        if ok2 then return true end
    end
    return DropViaCAS(Enum.KeyCode.DPadDown)
end

local QMethods,QNames={DropViaKeyboard,DropViaGamepad,DropViaTouch},{"Q (Keyboard)","DPadDown (Gamepad)","Drop button (Touch)"}

local function ToolSet()
    local set={}
    local bp=LP:FindFirstChild("Backpack")
    if bp then for _,t in ipairs(bp:GetChildren()) do if t:IsA("Tool") then set[t]=true end end end
    local ch=LP.Character
    if ch then for _,t in ipairs(ch:GetChildren()) do if t:IsA("Tool") then set[t]=true end end end
    return set
end

local function ToolGone(t)
    local bp=LP:FindFirstChild("Backpack")
    return not t.Parent or (t.Parent~=LP.Character and t.Parent~=bp)
end

local Carried={} -- tools that appeared in the inventory after grabbing an ore


local function GrabOre(o)
    local before=ToolSet()
    if not FirePx(o) then return false,"No enabled E interaction prompt in range." end
    task.wait(0.65)

    local added=0
    for t in pairs(ToolSet()) do
        if not before[t] then
            Carried[#Carried+1]=t
            added=added+1
        end
    end

    if added>0 or not o:IsDescendantOf(WS) then return true end
    return false,"The prompt was activated, but the item was not added to the inventory."
end

-- Drops carried tools using the game's real DropItem bindings and verifies each result.
local function DropCarried(expected)
    local tools={}
    for _,t in ipairs(Carried) do if t and t.Parent then tools[#tools+1]=t end end
    Carried={}
    if #tools==0 then return math.max(0,expected or 0) end

    local left=0
    for _,t in ipairs(tools) do
        if not Running() then return left end
        if t.Parent and t.Parent~=LP.Character then EquipTool(t) end
        local methods={}
        if UIS.TouchEnabled and not UIS.KeyboardEnabled then
            methods={DropViaTouch,DropViaGamepad,DropViaKeyboard}
        elseif UIS.GamepadEnabled and not UIS.KeyboardEnabled then
            methods={DropViaGamepad,DropViaTouch,DropViaKeyboard}
        else
            methods={DropViaKeyboard,DropViaGamepad,DropViaTouch}
        end
        for _,method in ipairs(methods) do
            if ToolGone(t) then break end
            pcall(method)
            task.wait(0.35)
        end
        if not ToolGone(t) then left=left+1 end
    end
    return left
end

-- Takes up to 2 ores, always going for the farthest one first.
-- Ores with no safe platform nearby are skipped (and ignored for 2 minutes) instead of teleporting
-- into the void.
local function CollectTwo(refPos,label,minDist)
    Carried={}
    local picked={}
    local tries,skips=0,0
    while #picked<2 and tries<6 and skips<40 and Running() do
        tries=tries+1
        local o=FarthestOre(refPos,picked,minDist)
        if not o then break end
        local pos=GetPos(o)
        Bad[o]=os.clock()+20 -- never repeat the same ore if it fails
        if pos then
            SLbl:Set(label.." ("..(#picked+1).."/2)")
            local res=OreTp(o,pos,C.manualDelay)
            if res=="dead" then return picked,false end
            if res=="skip" then
                Bad[o]=os.clock()+120
                tries=tries-1;skips=skips+1
            else
                task.wait(0.3)
                if GrabOre(o) then picked[#picked+1]=o end
                task.wait(0.35)
            end
        end
    end
    return picked,true
end

----------------------------------------------------------------
-- ESP (optimized + long range)
-- * One loop (every 0.25s) instead of one per frame + one per object
-- * Uses the index (no map scan)
-- * Every object inside the distance gets a NAME LABEL (BillboardGui, no render limit, visible from
--   very far). Only the closest ones also get the OUTLINE (Highlight): Roblox only renders 31 of them
--   at once, and that limit was what made far objects look "missing" until you got close.
-- * If the map uses StreamingEnabled, objects that are far away do not exist on your client at all,
--   so no script can draw them until they load.
-- * Highlights/Billboards live in their own folder (not inside the game)
----------------------------------------------------------------
local ESPTbl={}
local ESPFolder
local function GetFolder()
    if ESPFolder and ESPFolder.Parent then return ESPFolder end
    ESPFolder=Instance.new("Folder")
    ESPFolder.Name="_esp"
    local ok=pcall(function() ESPFolder.Parent=(gethui and gethui()) or game:GetService("CoreGui") end)
    if not ok or not ESPFolder.Parent then ESPFolder.Parent=CAM end
    return ESPFolder
end

RemESP=function(o)
    local e=ESPTbl[o]
    if e then
        if e.h then pcall(function() e.h:Destroy() end) end
        pcall(function() e.b:Destroy() end)
        ESPTbl[o]=nil
    end
end

local function AddESP(o,cat,oc,part)
    local folder=GetFolder()
    local bb=Instance.new("BillboardGui")
    bb.AlwaysOnTop=true;bb.Size=UDim2.new(0,120,0,40);bb.StudsOffset=Vector3.new(0,3,0)
    bb.MaxDistance=math.huge;bb.LightInfluence=0;bb.ResetOnSpawn=false
    bb.Adornee=part;bb.Parent=folder
    local tl=Instance.new("TextLabel",bb)
    tl.BackgroundTransparency=1;tl.Size=UDim2.new(1,0,1,0)
    tl.TextColor3=oc;tl.TextStrokeTransparency=0.4
    tl.Font=Enum.Font.GothamBold;tl.TextSize=13;tl.Text=""
    local e={b=bb,tl=tl,cat=cat,h=nil}
    ESPTbl[o]=e
    return e
end

local function SetOutline(e,o,on,fc,oc,ft)
    if on then
        if not e.h then
            local h=Instance.new("Highlight")
            h.FillTransparency=ft;h.OutlineTransparency=0
            h.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
            h.Adornee=o;h.Parent=GetFolder()
            e.h=h
        end
        e.h.FillColor=fc;e.h.OutlineColor=oc
    elseif e.h then
        pcall(function() e.h:Destroy() end)
        e.h=nil
    end
    if e.h then e.h.Adornee=o end
    e.tl.TextColor3=oc
end

local function ClearESP(cat)
    for o,e in pairs(ESPTbl) do
        if not cat or e.cat==cat then RemESP(o) end
    end
end

local function UpdateESP()
    local camPos=(WS.CurrentCamera or CAM).CFrame.Position
    local want={}

    local function Pick(cat,list,fc,oc,ft)
        table.sort(list,function(a,b) return a.d<b.d end)
        for i=1,math.min(#list,C.espLabelMax) do
            local it=list[i]
            want[it.o]=true
            local e=ESPTbl[it.o]
            if not e then e=AddESP(it.o,cat,oc,it.part) end
            if e then
                if e.b.Adornee~=it.part then e.b.Adornee=it.part end
                local outlineTarget=it.o:IsA("Tool") and it.part or it.o
                SetOutline(e,outlineTarget,i<=C.espMax,fc,oc,ft)
                if C.names then
                    e.tl.Text=C.dist and (it.lbl.."\n["..math.floor(it.d).."m]") or it.lbl
                else
                    e.tl.Text=""
                end
            end
        end
    end

    if C.mESP and IndexReady then
        local list={}
        for m in pairs(MonSet) do
            if m.Parent and not (m:IsA("Model") and PL:GetPlayerFromCharacter(m)) then
                local part=PartOf(m)
                if part then
                    local d=(camPos-part.Position).Magnitude
                    if d<=C.espDist then list[#list+1]={o=m,part=part,d=d,lbl=m.Name} end
                end
            else
                MonSet[m]=nil
            end
        end
        Pick("m",list,C.mCol,Color3.new(1,1,1),0.6)
    end

    if C.oESP and IndexReady then
        local list={}
        for o,n in pairs(OreSet) do
            if o.Parent then
                if C.espItems[n]~=false and not MonSet[o] then
                    local part=PartOf(o)
                    if part then
                        local d=(camPos-part.Position).Magnitude
                        if d<=C.espDist then
                            local label=n=="Amber Ore" and "Amber Ore" or n
                            list[#list+1]={o=o,part=part,d=d,lbl=label}
                        end
                    end
                end
            else
                OreSet[o]=nil
            end
        end
        Pick("o",list,C.oCol,Color3.new(0,0.9,1),0.7)
    end

    if C.sESP and IndexReady then
        local list={}
        for shard in pairs(ShardSet) do
            if shard.Parent and shard:IsA("UnionOperation") and shard.Name=="Shard" then
                local part=shard
                local d=(camPos-part.Position).Magnitude
                if d<=C.espDist then
                    list[#list+1]={o=shard,part=part,d=d,lbl="Shard"}
                end
            else
                ShardSet[shard]=nil
            end
        end
        Pick("s",list,C.sCol,C.sCol,0.7)
    end

    if C.pESP then
        local list={}
        for _,p in ipairs(PL:GetPlayers()) do
            local ch=p.Character
            if p~=LP and ch and ch.Parent then
                local part=ch:FindFirstChild("HumanoidRootPart")
                if part then
                    local d=(camPos-part.Position).Magnitude
                    if d<=C.espDist then list[#list+1]={o=ch,part=part,d=d,lbl=p.Name} end
                end
            end
        end
        Pick("p",list,C.pCol,Color3.new(1,1,1),0.6)
    end

    for o in pairs(ESPTbl) do
        if not want[o] or not o.Parent then RemESP(o) end
    end
end

task.spawn(function()
    while Alive do
        if C.mESP or C.oESP or C.pESP or C.sESP then
            pcall(UpdateESP)
            task.wait(C.espRate)
        else
            task.wait(0.5)
        end
    end
end)

----------------------------------------------------------------
-- SHARD COLLECTION
----------------------------------------------------------------
local ShardMissingNotified=false

local function GetShardCandidates()
    local spawn=GetSpawn()
    local root=Root()
    local origin=(spawn and spawn.Position) or (root and root.Position)
    local found={}
    if not origin then return found end

    for shard in pairs(ShardSet) do
        if shard and shard.Parent and shard:IsA("UnionOperation") and shard.Name=="Shard" then
            local pos=shard.Position
            local distance=(pos-origin).Magnitude
            -- Same spawn-centered safety box as item collection, plus a strict 600-stud radius.
            if distance<=600 and IsWithinBaseRange(pos) then
                found[#found+1]={object=shard,pos=pos,distance=distance}
            end
        else
            ShardSet[shard]=nil
        end
    end
    table.sort(found,function(a,b) return a.distance>b.distance end)
    return found
end

local function CurrCycle(force)
    if not IndexReady then return false,"Map still indexing." end
    if not IsAlive() then return false,"No character available." end

    local found=GetShardCandidates()
    if #found==0 then
        if not ShardMissingNotified then
            RF:Notify({Title="Shards not found",Content="No UnionOperation named Shard was found within 600 studs of spawn.",Duration=5})
            ShardMissingNotified=true
        end
        return false,"No Shards found."
    end

    ShardMissingNotified=false
    local collected=0
    local failed=0
    for _,entry in ipairs(found) do
        if not force and not C.cur then break end
        local shard=entry.object
        if shard and shard.Parent then
            local res=OreTp(shard,entry.pos,0)
            if res=="ok" then
                local prompt=FindOrePrompt(shard)
                if prompt and FireSpecificPrompt(prompt) then
                    collected=collected+1
                    -- Let the game process the server-side pickup before moving again.
                    task.wait(force and 0.025 or 0.12)
                else
                    failed=failed+1
                end
            else
                failed=failed+1
            end
        end
    end
    return collected>0,collected,failed
end
----------------------------------------------------------------
-- MANUAL COLLECT
----------------------------------------------------------------
local function ManCollect(name)
    local r=Root()
    if not r or not IsAlive() then
        RF:Notify({Title="Error",Content="No character available.",Duration=5})
        return
    end
    if not IndexReady then
        RF:Notify({Title="Wait",Content="The map is still being indexed.",Duration=5})
        return
    end

    local savedCF=r.CFrame
    local o=NearestOre(name,{})
    if not o then
        RF:Notify({Title="Item not found",Content=name.." was not found inside the base range (600 studs each side, 250 vertical) or monsters are nearby.",Duration=5})
        return
    end

    local pos=GetPos(o)
    if not pos then
        RF:Notify({Title="Error",Content="Could not read the mineral position.",Duration=5})
        return
    end

    local res=OreTp(o,pos,C.manualDelay)
    if res=="skip" then
        RF:Notify({Title="Unsafe mineral",Content="No safe platform close enough to interact with "..name..".",Duration=5})
        return
    elseif res~="ok" then
        RF:Notify({Title="Teleport failed",Content="Could not reach "..name..".",Duration=5})
        return
    end

    task.wait(C.manualDelay)
    local grabbed,reason=GrabOre(o)
    task.wait(math.max(0.25,C.manualDelay))

    if C.ret then
        local spawn=GetSpawn()
        if spawn then
            SafeTp(spawn.Position)
        else
            local r2=Root()
            if r2 then r2.CFrame=savedCF end
        end
    end

    if grabbed then
        RF:Notify({Title="Item collected",Content=name.." was picked up. Returning to spawn.",Duration=5})
    else
        RF:Notify({Title="Pickup failed",Content=reason or ("Could not collect "..name.."."),Duration=5})
    end
end

----------------------------------------------------------------
-- SELLING SPOT
----------------------------------------------------------------
local function GetSellingSpot()
    local placed=WS:FindFirstChild("PlacedTiles")
    local station=placed and placed:FindFirstChild("SellStation")
    local spot=station and station:FindFirstChild("SellingSpot")
    if not spot then return nil,nil end
    local prompt=spot:FindFirstChildWhichIsA("ProximityPrompt",true)
    if not spot:IsA("BasePart") then
        local part=spot:FindFirstChildWhichIsA("BasePart",true)
        return part,prompt
    end
    return spot,prompt
end

local function SellAtSellingSpot(itemName,delay)
    local spot,prompt=GetSellingSpot()
    if not spot or not prompt then
        return false,"Workspace.PlacedTiles.SellStation.SellingSpot.ProximityPrompt was not found."
    end
    -- Teleport directly above SellingSpot (not merely to a nearby floor hit).
    local topY=spot.Position.Y + (spot:IsA("BasePart") and spot.Size.Y*0.5 or 0)
    local target=Vector3.new(spot.Position.X,topY+3.2,spot.Position.Z)
    if not TpTo(target,0.08) then
        return false,"Could not reach SellingSpot."
    end
    task.wait(math.max(0,delay or 0))
    if not FireSpecificPrompt(prompt) then
        return false,"SellingSpot prompt could not be activated. Check its activation distance."
    end
    task.wait(0.25)
    return true
end

----------------------------------------------------------------
-- AUTO FARM / AUTO BRING
----------------------------------------------------------------
local AutoItemsRunning=false
local function StartAutoItems()
    if AutoItemsRunning then return end
    AutoItemsRunning=true
    task.spawn(function()
        while Alive and (C.autoFarm or C.autoBring) do
            if not IndexReady or not IsAlive() then
                task.wait(0.5)
            else
                local spawn=GetSpawn()
                local root=Root()
                local basePos=spawn and spawn.Position or (root and root.Position)
                -- Ignore the small drop zone around spawn so a dropped item is not picked up again forever.
                local item=basePos and FarthestOre(basePos,{},8) or nil
                if not item then
                    task.wait(0.65)
                else
                    local itemName=OreSet[item] or item.Name
                    local delay=C.autoFarm and C.farmDelay or C.bringDelay
                    local pos=GetPos(item)
                    local result=pos and OreTp(item,pos,delay) or "skip"
                    if result=="ok" then
                        task.wait(delay)
                        Carried={}
                        local got,why=GrabOre(item)
                        if got then
                            task.wait(delay)
                            if C.autoFarm then
                                local sold,why=SellAtSellingSpot(itemName,delay)
                                if not sold then
                                    RF:Notify({Title="Selling failed",Content=why or ("Could not sell "..itemName.."."),Duration=5})
                                    Bad[item]=os.clock()+20
                                end
                                Carried={}
                            else
                                local target=GetSpawn()
                                if target and SafeTp(target.Position) then
                                    task.wait(delay)
                                    local left=DropCarried(1)
                                    if left>0 then
                                        RF:Notify({Title="Drop failed",Content=itemName.." was collected but the game did not drop it. Check the DropItem action.",Duration=5})
                                        Bad[item]=os.clock()+20
                                    end
                                else
                                    RF:Notify({Title="Return failed",Content="Could not return to spawn with "..itemName..".",Duration=5})
                                    Bad[item]=os.clock()+20
                                end
                            end
                        else
                            Bad[item]=os.clock()+12
                            if why then SLbl:Set("Pickup failed: "..itemName) end
                        end
                    elseif result=="skip" then
                        Bad[item]=os.clock()+120
                    end
                    task.wait(delay)
                end
            end
        end
        AutoItemsRunning=false
    end)
end

----------------------------------------------------------------
-- NOCLIP (remembers the original CanCollide of every part and restores it)
----------------------------------------------------------------
local NocConn
local NocOrig=setmetatable({}, {__mode="k"})
local function SetNoclip(v)
    C.noclip=v
    if NocConn then NocConn:Disconnect();NocConn=nil end
    if v then
        NocConn=RS.Stepped:Connect(function()
            local ch=LP.Character
            if ch then
                for _,p in ipairs(ch:GetDescendants()) do
                    if p:IsA("BasePart") then
                        if NocOrig[p]==nil then NocOrig[p]=p.CanCollide end
                        p.CanCollide=false
                    end
                end
            end
        end)
    else
        for p,val in pairs(NocOrig) do
            if p.Parent then p.CanCollide=val end
        end
        table.clear(NocOrig)
    end
end

----------------------------------------------------------------
-- FLY
----------------------------------------------------------------
local FlyC,FlyBV,FlyAt
local function SetFly(v)
    C.fly=v
    if v then
        local ch=LP.Character;local rt=Root()
        if not rt or not ch then return end
        local hm=ch:FindFirstChildOfClass("Humanoid")
        if hm then hm.PlatformStand=true end
        FlyAt=Instance.new("Attachment",rt)
        FlyBV=Instance.new("BodyVelocity",rt)
        FlyBV.MaxForce=Vector3.new(1e5,1e5,1e5);FlyBV.Velocity=Vector3.zero
        FlyC=RS.Heartbeat:Connect(function()
            if not FlyBV or not FlyBV.Parent then SetFly(false);return end
            local cm=(WS.CurrentCamera or CAM).CFrame;local vl=Vector3.zero
            if UIS:IsKeyDown(Enum.KeyCode.W) then vl=vl+cm.LookVector end
            if UIS:IsKeyDown(Enum.KeyCode.S) then vl=vl-cm.LookVector end
            if UIS:IsKeyDown(Enum.KeyCode.A) then vl=vl-cm.RightVector end
            if UIS:IsKeyDown(Enum.KeyCode.D) then vl=vl+cm.RightVector end
            if UIS:IsKeyDown(Enum.KeyCode.Space) then vl=vl+Vector3.new(0,1,0) end
            if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then vl=vl-Vector3.new(0,1,0) end
            FlyBV.Velocity=vl*50
        end)
    else
        if FlyC then FlyC:Disconnect();FlyC=nil end
        if FlyBV then FlyBV:Destroy();FlyBV=nil end
        if FlyAt then FlyAt:Destroy();FlyAt=nil end
        local ch=LP.Character
        if ch then local hm=ch:FindFirstChildOfClass("Humanoid");if hm then hm.PlatformStand=false end end
    end
end

----------------------------------------------------------------
-- INFINITE JUMP (every jump request, including in mid-air, makes you jump again)
----------------------------------------------------------------
local JumpConn
local function SetInfJump(v)
    C.ij=v
    if JumpConn then JumpConn:Disconnect();JumpConn=nil end
    if v then
        JumpConn=UIS.JumpRequest:Connect(function()
            local ch=LP.Character
            local hm=ch and ch:FindFirstChildOfClass("Humanoid")
            if hm and hm.Health>0 then hm:ChangeState(Enum.HumanoidStateType.Jumping) end
        end)
    end
end

----------------------------------------------------------------
-- ANTI AFK
----------------------------------------------------------------
local AfkT
local function SetAFK(v)
    C.afk=v
    if v then
        AfkT=task.spawn(function()
            while C.afk and Alive do
                task.wait(60)
                if not C.afk or not Alive then break end
                local ch=LP.Character
                if ch then
                    local hm=ch:FindFirstChildOfClass("Humanoid")
                    if hm then hm.Jump=true end
                end
            end
        end)
    else
        if AfkT then task.cancel(AfkT);AfkT=nil end
    end
end

----------------------------------------------------------------
-- FULLBRIGHT (see in dark places)
----------------------------------------------------------------
local FB_TARGET={
    Brightness=2,
    ClockTime=14,
    FogEnd=1e5,
    GlobalShadows=false,
    Ambient=Color3.fromRGB(178,178,178),
    OutdoorAmbient=Color3.fromRGB(178,178,178),
}
local FB_ORIG={}
local FB_ATM={}
local FB_HOOKED=false

local function FBAtmo(a)
    if a:IsA("Atmosphere") then
        if not FB_ATM[a] then FB_ATM[a]={a.Density,a.Haze} end
        a.Density=0;a.Haze=0
    end
end

local function SetFullbright(v)
    C.fb=v
    if v then
        for k,val in pairs(FB_TARGET) do
            if FB_ORIG[k]==nil then FB_ORIG[k]=Lighting[k] end
            Lighting[k]=val
        end
        for _,c in ipairs(Lighting:GetChildren()) do FBAtmo(c) end
        if not FB_HOOKED then
            FB_HOOKED=true
            -- if the game darkens the lighting again, fix it instantly
            for k,val in pairs(FB_TARGET) do
                Bind(Lighting:GetPropertyChangedSignal(k),function()
                    if C.fb and Lighting[k]~=val then Lighting[k]=val end
                end)
            end
            Bind(Lighting.ChildAdded,function(c) if C.fb then FBAtmo(c) end end)
        end
    else
        for k,val in pairs(FB_ORIG) do Lighting[k]=val end
        FB_ORIG={}
        for a,vals in pairs(FB_ATM) do
            if a.Parent then a.Density=vals[1];a.Haze=vals[2] end
        end
        FB_ATM={}
    end
end

----------------------------------------------------------------
-- SPECTATE
----------------------------------------------------------------
local SpecName,SpecDD,SpecLbl
local SpecActive=false

local function PlayerNames()
    local t={}
    for _,p in ipairs(PL:GetPlayers()) do
        if p~=LP then t[#t+1]=p.Name end
    end
    table.sort(t)
    return t
end

local function StopSpectate()
    SpecActive=false
    local cam=WS.CurrentCamera
    local ch=LP.Character
    local h=ch and ch:FindFirstChildOfClass("Humanoid")
    if cam and h then cam.CameraSubject=h end
    if SpecLbl then SpecLbl:Set("Spectating: nobody") end
end

local function StartSpectate()
    local p=SpecName and PL:FindFirstChild(SpecName)
    if not p then
        RF:Notify({Title="Spectate",Content="Select a player first.",Duration=2})
        return
    end
    SpecActive=true
    SpecLbl:Set("Spectating: "..p.Name)
    local h=p.Character and p.Character:FindFirstChildOfClass("Humanoid")
    local cam=WS.CurrentCamera
    if h and cam then cam.CameraSubject=h end
end

-- If the player respawns or the game resets the camera, focus again; if they leave, stop spectating
task.spawn(function()
    while Alive do
        task.wait(0.4)
        if SpecActive then
            local p=SpecName and PL:FindFirstChild(SpecName)
            if not p then
                StopSpectate()
                RF:Notify({Title="Spectate",Content="Player left the server.",Duration=3})
            else
                local h=p.Character and p.Character:FindFirstChildOfClass("Humanoid")
                local cam=WS.CurrentCamera
                if h and cam and cam.CameraSubject~=h then cam.CameraSubject=h end
            end
        end
    end
end)

local function RefreshPlayers()
    if SpecDD then pcall(function() SpecDD:Refresh(PlayerNames()) end) end
end
Bind(PL.PlayerAdded,function() task.wait(0.5);RefreshPlayers() end)
Bind(PL.PlayerRemoving,function(p)
    if p.Name==SpecName and SpecActive then StopSpectate() end
    task.wait(0.2);RefreshPlayers()
end)

