-- Top-right toast notifications: slide in from the right, stay 5 seconds, slide out.
local ToastGui=make("ScreenGui",{
    Name="K24ToastNotifications",ResetOnSpawn=false,IgnoreGuiInset=true,
    DisplayOrder=10001,ZIndexBehavior=Enum.ZIndexBehavior.Sibling,
})
guiParent(ToastGui)
local ToastItems={}

local function LayoutToasts()
    for i,item in ipairs(ToastItems) do
        if item and item.Parent then
            tween(item,0.28,{Position=UDim2.new(1,-18,0,16+(i-1)*82)},Enum.EasingStyle.Quint)
        end
    end
end

local function ShowToast(o)
    if not Alive then return end
    if #ToastItems>=5 then
        local old=table.remove(ToastItems,1)
        if old then old:Destroy() end
    end

    local title=tostring(o.Title or "K24 HUB")
    local content=tostring(o.Content or "")
    local lower=string.lower(title)
    local accent=(string.find(lower,"error",1,true) or string.find(lower,"failed",1,true)
        or string.find(lower,"not found",1,true) or string.find(lower,"fail",1,true))
        and Theme.red or Theme.cyan

    local card=make("Frame",{
        Name="Toast",AnchorPoint=Vector2.new(1,0),
        Position=UDim2.new(1,330,0,16),Size=UDim2.fromOffset(310,70),
        BackgroundColor3=Theme.navy,BackgroundTransparency=0.06,BorderSizePixel=0,
        ZIndex=100,
    },ToastGui)
    round(card,10);stroke(card,accent,1.5,0.12)
    make("Frame",{
        Position=UDim2.fromOffset(0,8),Size=UDim2.new(0,4,1,-16),
        BackgroundColor3=accent,BorderSizePixel=0,ZIndex=101,
    },card)
    local head=make("TextLabel",{
        BackgroundTransparency=1,Position=UDim2.fromOffset(14,7),Size=UDim2.new(1,-24,0,22),
        Font=Enum.Font.GothamBold,Text=title,TextSize=14,TextColor3=Theme.white,
        TextXAlignment=Enum.TextXAlignment.Left,TextTruncate=Enum.TextTruncate.AtEnd,ZIndex=102,
    },card)
    local body=make("TextLabel",{
        BackgroundTransparency=1,Position=UDim2.fromOffset(14,30),Size=UDim2.new(1,-24,1,-36),
        Font=Enum.Font.Gotham,Text=content,TextSize=12,TextColor3=Color3.fromRGB(220,235,255),
        TextWrapped=true,TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top,
        TextTruncate=Enum.TextTruncate.AtEnd,ZIndex=102,
    },card)

    table.insert(ToastItems,card)
    LayoutToasts()

    task.delay(5,function()
        if not card.Parent then return end
        local y=card.Position.Y.Offset
        tween(card,0.3,{Position=UDim2.new(1,330,0,y),BackgroundTransparency=1},Enum.EasingStyle.Quint,Enum.EasingDirection.In)
        tween(head,0.2,{TextTransparency=1})
        tween(body,0.2,{TextTransparency=1})
        task.delay(0.32,function()
            for i,item in ipairs(ToastItems) do
                if item==card then table.remove(ToastItems,i);break end
            end
            if card.Parent then card:Destroy() end
            LayoutToasts()
        end)
    end)
end

