----------------------------------------------------------------
-- ORE COUNTER (uses the index, no map scan)
----------------------------------------------------------------
local function RefreshCount()
    local seen,ct={},0
    for o,n in pairs(OreSet) do
        if o.Parent and not seen[n] then seen[n]=true;ct=ct+1 end
    end
    CLbl:Set("Items on Map: "..ct.." / "..#ORES.." types")
end

task.spawn(function()
    WaitIndex()
    if not Alive then return end
    RefreshCount()
    while Alive do
        task.wait(10)
        if Alive and C.ref then
            RefreshCount()
            SLbl:Set("Status: Idle | "..os.date("%H:%M:%S"))
        end
    end
end)

----------------------------------------------------------------
-- UNLOAD (X button, or running the script again)
-- Leaves everything exactly as if the script had never run:
--  * every remaining feature is turned off (currency, ESP, fly, noclip, infinite jump...)
--  * ESP objects, Fullbright lighting, ProximityPrompt hold times, camera, WalkSpeed/Jump and
--    CanCollide are restored
--  * every connection is disconnected and every background loop stops
--  * the menu and the cached texture file are deleted
----------------------------------------------------------------
local Unloaded=false
Unload=function()
    if Unloaded then return end
    Unloaded=true
    Alive=false
    C.cur=false
    C.autoFarm=false;C.autoBring=false
    C.mESP=false;C.oESP=false;C.pESP=false;C.sESP=false

    pcall(ClearESP)
    pcall(function()
        if ESPFolder then ESPFolder:Destroy();ESPFolder=nil end
    end)
    pcall(SetFullbright,false)
    pcall(SetFly,false)
    pcall(SetNoclip,false)
    pcall(SetInfJump,false)
    pcall(SetAFK,false)
    pcall(SetInstant,false)
    pcall(StopSpectate)
    pcall(SetShiftLock,false)
    pcall(RestoreMovement)
    C.lockSpd=false
    pcall(function()
        RS:UnbindFromRenderStep(LOCK_STEP)
    end)

    for _,c in ipairs(Conns) do pcall(function() c:Disconnect() end) end
    Conns={}

    for _,t in ipairs({OreSet,CurrSet,SellSet,MonSet,Spawns,ShardSet,Prompts,Bad,Carried,ESPTbl}) do
        pcall(table.clear,t)
    end
    LastSafe=nil;LockHum=nil;SellCache=nil;SpawnCache=nil

    ENV.K24HUB_Unload=nil
    pcall(function() if ToastGui then ToastGui:Destroy() end end)
    table.clear(ToastItems)
    pcall(function() if Win and Win.Gui then Win.Gui:Destroy() end end)
    pcall(function()
        if delfile and isfile and isfile(STUD_FILE) then delfile(STUD_FILE) end
    end)
end
ENV.K24HUB_Unload=function() if Unload then Unload() end end

RF:Notify({Title="FATAL FLOORS HUB",Content="Loaded! Menu key: RightShift (changeable in Settings) or the K24 button.",Duration=4})
